function planItemsForDay(day){if(!day.schedule)return day.places.map(placeId=>({id:uid(),placeId,name:translateText(samples.find(p=>p.id===placeId).name),time:'',note:translateText(tokyoVisitGuides[placeId]?.duration||'')}));return day.schedule.map(([placeId,time,note])=>({id:uid(),placeId,name:placeId===null?translateText(note):translateText(samples.find(p=>p.id===placeId).name),time,note:placeId===null?'':translateText(note)}))}
function renderRoutePlanning(route,detail){const g=routePlanning[route.id];if(!g)return;const box=document.createElement('section');box.className='routePlanning';box.innerHTML=`<h4>하루의 흐름</h4><dl><div><dt>출발 → 도착</dt><dd>${g.start} → ${g.end}</dd></div><div><dt>이동</dt><dd>${g.move}</dd></div><div><dt>식사</dt><dd>${g.meal}</dd></div><div><dt>비 오는 날</dt><dd>${g.rain}</dd></div><div><dt>줄여도 좋은 일정</dt><dd>${g.skip}</dd></div></dl><p>${g.warning}</p><h4>수정 가능한 시간표 예시</h4><ol class="routeTimeline">${g.schedule.map(([id,time,note])=>`<li><time>${time}</time><span>${id===null?note:samples.find(p=>p.id===id).name}<small>${id===null?'식사·휴식':note}</small></span></li>`).join('')}</ol><p class="muted">시각은 여행 계획을 돕는 예시이며 운영시간·교통편을 보장하지 않습니다.</p>`;detail.append(box);}

